import hashlib, hmac, time

def from_pando(key: str, headers, body: bytes) -> bool:
    ts = headers["Pando-Timestamp"]
    if abs(time.time() - int(ts)) > 300:
        return False
    mac = hmac.new(key.encode(), ts.encode() + b"." + body, hashlib.sha256).hexdigest()
    return hmac.compare_digest("v1=" + mac, headers["Pando-Signature"])
